// Generated by Copilot
import { useState } from "react";
import { Box, Typography, IconButton } from "@mui/material";
import {
  Building2,
  MapPin,
  Search,
  CheckCircle2,
  XCircle,
  Award,
  BarChart2,
  Eye,
  X,
} from "lucide-react";
import {
  HOSPITALS,
  CITIES,
  SPECIALTIES,
  STATUSES,
  SPEC_COLORS,
  INIT_BG,
  INIT_TEXT,
  fmtINR,
  fmtL,
} from "../../pages/HRPortalHospitals/data";
import type { Hospital } from "../../pages/HRPortalHospitals/data";
import { HospitalKpiCard } from "../HospitalKpiCard";
import {
  SpecTag,
  CashlessChip,
  HStatusChip,
  ViewBtn,
  FilterSelect,
  PageBtn,
} from "./styles";
import {
  SectionCard,
  StyledTable,
  StyledTh,
  StyledTd,
  SearchBox,
} from "../../pages/HRPortal/styles";
import { useLocalization } from "@ui/ui-lib";

const PER_PAGE = 8;

interface HospitalNetworkTabProps {
  policyCode: string;
}

export function HospitalNetworkTab({ policyCode }: HospitalNetworkTabProps) {
  const { localizationData } = useLocalization();
  const [_search, _setSearch] = useState("");
  const [_cityFilter, _setCityFilter] = useState("All Cities");
  const [_specFilter, _setSpecFilter] = useState("All Specialties");
  const [_statusFilter, _setStatusFilter] = useState("All Status");
  const [_cashlessFilter, _setCashlessFilter] = useState("All");
  const [_page, _setPage] = useState(1);

  const _filtered: Hospital[] = HOSPITALS.filter((h) => {
    const _q = _search.toLowerCase();
    if (
      _q &&
      !h.name.toLowerCase().includes(_q) &&
      !h.city.toLowerCase().includes(_q)
    )
      return false;
    if (_cityFilter !== "All Cities" && h.city !== _cityFilter) return false;
    if (
      _specFilter !== "All Specialties" &&
      !h.specialities.includes(_specFilter)
    )
      return false;
    if (_statusFilter !== "All Status" && h.status !== _statusFilter)
      return false;
    if (_cashlessFilter === "Yes" && !h.cashless) return false;
    if (_cashlessFilter === "No" && h.cashless) return false;
    return true;
  });

  const _totalPages = Math.max(1, Math.ceil(_filtered.length / PER_PAGE));
  const _pageRows = _filtered.slice((_page - 1) * PER_PAGE, _page * PER_PAGE);
  const _hasFilters =
    _cityFilter !== "All Cities" ||
    _specFilter !== "All Specialties" ||
    _statusFilter !== "All Status" ||
    _cashlessFilter !== "All";

  const _clearFilters = () => {
    _setCityFilter("All Cities");
    _setSpecFilter("All Specialties");
    _setStatusFilter("All Status");
    _setCashlessFilter("All");
    _setPage(1);
  };

  const _topH = HOSPITALS.reduce((a, b) =>
    a.totalClaims > b.totalClaims ? a : b,
  );
  const _hospitalsUsed = HOSPITALS.filter(
    (h) => h.totalClaims > 0 && h.status !== "Inactive",
  ).length;
  const _grandTotal = HOSPITALS.reduce((s, h) => s + h.totalAmount, 0);
  const _avgPerHosp = Math.round(_grandTotal / HOSPITALS.length);
  const _uniqueCities = Array.from(
    new Set(HOSPITALS.map((h) => h.city)),
  ).length;

  return (
    <Box>
      {/* Page header */}
      <Box sx={{ mb: 3 }}>
        <Typography sx={{ fontSize: 20, fontWeight: 700, color: "#111827" }}>
          Network Hospital Directory
        </Typography>
        <Typography sx={{ fontSize: 13, color: "#6b7280", mt: 0.25 }}>
          {HOSPITALS.length} empanelled hospitals · {policyCode}
        </Typography>
      </Box>

      {/* KPI grid */}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: "repeat(4, 1fr)",
          gap: 2.5,
          mb: 3,
        }}
      >
        <HospitalKpiCard
          icon={Building2}
          iconColor="#3b82f6"
          iconBg="#eff6ff"
          accentColor="#3b82f6"
          label="Total Network Hospitals"
          value={String(HOSPITALS.length)}
          sub={`Across ${_uniqueCities} cities`}
        />
        <HospitalKpiCard
          icon={CheckCircle2}
          iconColor="#10b981"
          iconBg="#ecfdf5"
          accentColor="#10b981"
          label="Hospitals Used This Year"
          value={String(_hospitalsUsed)}
          sub={`${Math.round(
            (_hospitalsUsed / HOSPITALS.length) * 100,
          )}% network utilisation`}
        />
        <HospitalKpiCard
          icon={Award}
          iconColor="#f59e0b"
          iconBg="#fffbeb"
          accentColor="#f59e0b"
          label="Top Claim Hospital"
          value={_topH.name.split(" ")[0]}
          sub={`${_topH.totalClaims} claims · ${fmtL(_topH.totalAmount, localizationData?.data)}`}
        />
        <HospitalKpiCard
          icon={BarChart2}
          iconColor="#ef4444"
          iconBg="#fef2f2"
          accentColor="#ef4444"
          label="Avg Claim per Hospital"
          value={fmtINR(_avgPerHosp, localizationData?.data)}
          sub="Across all active hospitals"
        />
      </Box>

      {/* Filter bar */}
      <Box
        sx={{
          display: "flex",
          alignItems: "center",
          gap: 1.5,
          mb: 2,
          flexWrap: "wrap",
        }}
      >
        <SearchBox sx={{ maxWidth: 260 }}>
          <Search size={13} color="#9ca3af" />
          <input
            placeholder="Search hospital or city…"
            value={_search}
            onChange={(e) => {
              _setSearch(e.target.value);
              _setPage(1);
            }}
          />
          {_search && (
            <IconButton
              size="small"
              onClick={() => _setSearch("")}
              sx={{ p: 0 }}
            >
              <X size={12} color="#9ca3af" />
            </IconButton>
          )}
        </SearchBox>

        <FilterSelect
          value={_cityFilter}
          onChange={(e) => {
            _setCityFilter(e.target.value);
            _setPage(1);
          }}
        >
          {CITIES.map((o) => (
            <option key={o}>{o}</option>
          ))}
        </FilterSelect>
        <FilterSelect
          value={_specFilter}
          onChange={(e) => {
            _setSpecFilter(e.target.value);
            _setPage(1);
          }}
        >
          {SPECIALTIES.map((o) => (
            <option key={o}>{o}</option>
          ))}
        </FilterSelect>
        <FilterSelect
          value={_statusFilter}
          onChange={(e) => {
            _setStatusFilter(e.target.value);
            _setPage(1);
          }}
        >
          {STATUSES.map((o) => (
            <option key={o}>{o}</option>
          ))}
        </FilterSelect>
        <FilterSelect
          value={_cashlessFilter}
          onChange={(e) => {
            _setCashlessFilter(e.target.value);
            _setPage(1);
          }}
        >
          {["All", "Yes", "No"].map((o) => (
            <option key={o}>{o}</option>
          ))}
        </FilterSelect>

        {_hasFilters && (
          <Box
            onClick={_clearFilters}
            sx={{
              fontSize: 12,
              fontWeight: 600,
              color: "#2563eb",
              cursor: "pointer",
              "&:hover": { textDecoration: "underline" },
            }}
          >
            Clear filters
          </Box>
        )}
        <Typography sx={{ ml: "auto", fontSize: 12, color: "#9ca3af" }}>
          {_filtered.length} results
        </Typography>
      </Box>

      {/* Table */}
      <SectionCard sx={{ p: 0, overflow: "hidden", mb: 0 }}>
        <Box sx={{ overflowX: "auto" }}>
          <StyledTable>
            <thead>
              <tr>
                <StyledTh>Hospital Name</StyledTh>
                <StyledTh>City</StyledTh>
                <StyledTh>Specialities</StyledTh>
                <StyledTh>Cashless</StyledTh>
                <StyledTh>Total Claims</StyledTh>
                <StyledTh>Total Amount</StyledTh>
                <StyledTh>Avg Claim</StyledTh>
                <StyledTh>Status</StyledTh>
                <StyledTh>Action</StyledTh>
              </tr>
            </thead>
            <tbody>
              {_pageRows.length === 0 ? (
                <tr>
                  <td
                    colSpan={9}
                    style={{ textAlign: "center", padding: "48px 0" }}
                  >
                    <Building2
                      size={28}
                      color="#e5e7eb"
                      style={{ display: "block", margin: "0 auto 8px" }}
                    />
                    <Typography sx={{ fontSize: 13, color: "#9ca3af" }}>
                      No hospitals match your filters
                    </Typography>
                  </td>
                </tr>
              ) : (
                _pageRows.map((h) => (
                  <tr key={h.id}>
                    {/* Name */}
                    <StyledTd>
                      <Box
                        sx={{
                          display: "flex",
                          alignItems: "center",
                          gap: 1.25,
                        }}
                      >
                        <Box
                          sx={{
                            width: 34,
                            height: 34,
                            borderRadius: "10px",
                            flexShrink: 0,
                            backgroundColor: INIT_BG[h.initials] ?? "#f3f4f6",
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                          }}
                        >
                          <Typography
                            sx={{
                              fontSize: 11,
                              fontWeight: 700,
                              color: INIT_TEXT[h.initials] ?? "#374151",
                            }}
                          >
                            {h.initials}
                          </Typography>
                        </Box>
                        <Box>
                          <Typography
                            sx={{
                              fontSize: 13,
                              fontWeight: 600,
                              color: "#111827",
                            }}
                          >
                            {h.name}
                          </Typography>
                          <Typography sx={{ fontSize: 11, color: "#9ca3af" }}>
                            {h.type}
                          </Typography>
                        </Box>
                      </Box>
                    </StyledTd>

                    {/* City */}
                    <StyledTd>
                      <Box
                        sx={{ display: "flex", alignItems: "center", gap: 0.5 }}
                      >
                        <MapPin size={12} color="#9ca3af" />
                        <Box>
                          <Typography sx={{ fontSize: 12.5, color: "#374151" }}>
                            {h.city}
                          </Typography>
                          <Typography sx={{ fontSize: 11, color: "#9ca3af" }}>
                            {h.state}
                          </Typography>
                        </Box>
                      </Box>
                    </StyledTd>

                    {/* Specialities */}
                    <StyledTd>
                      <Box sx={{ display: "flex", gap: 0.5, flexWrap: "wrap" }}>
                        {h.specialities.slice(0, 2).map((spec) => (
                          <SpecTag
                            key={spec}
                            bg={`${SPEC_COLORS[spec] ?? "#6b7280"}18`}
                            textColor={SPEC_COLORS[spec] ?? "#6b7280"}
                          >
                            {spec}
                          </SpecTag>
                        ))}
                        {h.specialities.length > 2 && (
                          <SpecTag>+{h.specialities.length - 2}</SpecTag>
                        )}
                      </Box>
                    </StyledTd>

                    {/* Cashless */}
                    <StyledTd>
                      <CashlessChip active={h.cashless}>
                        {h.cashless ? (
                          <CheckCircle2 size={12} />
                        ) : (
                          <XCircle size={12} />
                        )}
                        {h.cashless ? "Yes" : "No"}
                      </CashlessChip>
                    </StyledTd>

                    <StyledTd sx={{ fontWeight: 700, color: "#111827" }}>
                      {h.totalClaims}
                    </StyledTd>
                    <StyledTd sx={{ fontWeight: 600 }}>
                      {fmtL(h.totalAmount, localizationData?.data)}
                    </StyledTd>
                    <StyledTd>{fmtINR(h.avgAmount, localizationData?.data)}</StyledTd>

                    {/* Status */}
                    <StyledTd>
                      <HStatusChip status={h.status}>{h.status}</HStatusChip>
                    </StyledTd>

                    {/* Action */}
                    <StyledTd>
                      <ViewBtn>
                        <Eye size={13} /> View Details
                      </ViewBtn>
                    </StyledTd>
                  </tr>
                ))
              )}
            </tbody>
          </StyledTable>
        </Box>

        {/* Pagination */}
        {_totalPages > 1 && (
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              px: 2.5,
              py: 1.5,
              borderTop: "1px solid #f3f4f6",
              backgroundColor: "rgba(249,250,251,0.6)",
            }}
          >
            <Typography sx={{ fontSize: 11, color: "#9ca3af" }}>
              Showing{" "}
              <Box component="span" sx={{ fontWeight: 600, color: "#374151" }}>
                {(_page - 1) * PER_PAGE + 1}–
                {Math.min(_page * PER_PAGE, _filtered.length)}
              </Box>{" "}
              of{" "}
              <Box component="span" sx={{ fontWeight: 600, color: "#374151" }}>
                {_filtered.length}
              </Box>
            </Typography>
            <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
              <PageBtn
                disabled={_page === 1}
                onClick={() => _setPage((p) => Math.max(1, p - 1))}
              >
                Previous
              </PageBtn>
              {Array.from({ length: _totalPages }, (_, i) => i + 1).map((p) => (
                <PageBtn
                  key={p}
                  active={_page === p}
                  onClick={() => _setPage(p)}
                >
                  {p}
                </PageBtn>
              ))}
              <PageBtn
                disabled={_page === _totalPages}
                onClick={() => _setPage((p) => Math.min(_totalPages, p + 1))}
              >
                Next
              </PageBtn>
            </Box>
          </Box>
        )}
      </SectionCard>
    </Box>
  );
}

export default HospitalNetworkTab;
